// Create Exam Page — Staff/Admin exam creation with question upload
import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import Layout from '../../components/common/Layout';
import { examAPI } from '../../services/api';
import toast from 'react-hot-toast';

const defaultQuestion = { question_text: '', option_a: '', option_b: '', option_c: '', option_d: '', correct_option: 'A', marks: 1, difficulty: 'medium' };

export default function CreateExamPage() {
  const navigate = useNavigate();
  const [step, setStep] = useState(1); // 1=Details, 2=Questions
  const [examData, setExamData] = useState({
    title: '', subject: '', department: '', description: '',
    duration_minutes: 60, total_marks: 100, pass_marks: 40,
    start_time: '', end_time: '', shuffle_questions: true,
    shuffle_options: true, proctoring_enabled: true
  });
  const [questions, setQuestions] = useState([{ ...defaultQuestion }]);
  const [createdExam, setCreatedExam] = useState(null);
  const [saving, setSaving] = useState(false);

  const updateExam = (field, value) => setExamData(prev => ({ ...prev, [field]: value }));

  const updateQuestion = (idx, field, value) => {
    setQuestions(prev => prev.map((q, i) => i === idx ? { ...q, [field]: value } : q));
  };

  const addQuestion = () => setQuestions(prev => [...prev, { ...defaultQuestion }]);
  const removeQuestion = (idx) => setQuestions(prev => prev.filter((_, i) => i !== idx));

  // Step 1: Create exam
  const handleCreateExam = async (e) => {
    e.preventDefault();
    setSaving(true);
    try {
      const data = await examAPI.create(examData);
      setCreatedExam(data.exam);
      toast.success('Exam created! Now add questions.');
      setStep(2);
    } catch {
      toast.error('Failed to create exam');
    } finally {
      setSaving(false);
    }
  };

  // Step 2: Save questions
  const handleSaveQuestions = async () => {
    if (!createdExam) return;
    const invalid = questions.find(q => !q.question_text || !q.option_a || !q.option_b || !q.option_c || !q.option_d);
    if (invalid) { toast.error('Please fill all question fields'); return; }

    setSaving(true);
    try {
      await examAPI.bulkAddQuestions(createdExam.id, { questions });
      toast.success(`${questions.length} questions saved!`);
      navigate('/staff/dashboard');
    } catch {
      toast.error('Failed to save questions');
    } finally {
      setSaving(false);
    }
  };

  return (
    <Layout title="Create Exam">
      {/* Steps indicator */}
      <div className="flex items-center gap-4 mb-8">
        {[{ n: 1, label: 'Exam Details' }, { n: 2, label: 'Questions' }].map(s => (
          <React.Fragment key={s.n}>
            <div className={`flex items-center gap-2 px-4 py-2 rounded-lg font-medium text-sm ${step >= s.n ? 'bg-blue-600 text-white' : 'bg-gray-100 text-gray-500'}`}>
              <span>{s.n}</span><span>{s.label}</span>
            </div>
            {s.n < 2 && <div className="h-0.5 w-8 bg-gray-200"/>}
          </React.Fragment>
        ))}
      </div>

      {/* Step 1: Exam Details */}
      {step === 1 && (
        <form onSubmit={handleCreateExam} className="max-w-2xl">
          <div className="bg-white rounded-xl shadow-sm p-6 space-y-5">
            <h2 className="font-bold text-gray-800 text-lg">Exam Details</h2>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <Field label="Exam Title *" value={examData.title} onChange={v => updateExam('title', v)} placeholder="e.g., Mathematics Mid-Term" required />
              <Field label="Subject *" value={examData.subject} onChange={v => updateExam('subject', v)} placeholder="e.g., Mathematics" required />
              <Field label="Department" value={examData.department} onChange={v => updateExam('department', v)} placeholder="e.g., Computer Science" />
              <Field label="Duration (minutes) *" type="number" value={examData.duration_minutes} onChange={v => updateExam('duration_minutes', parseInt(v))} required />
              <Field label="Total Marks *" type="number" value={examData.total_marks} onChange={v => updateExam('total_marks', parseInt(v))} required />
              <Field label="Pass Marks *" type="number" value={examData.pass_marks} onChange={v => updateExam('pass_marks', parseInt(v))} required />
              <Field label="Start Time *" type="datetime-local" value={examData.start_time} onChange={v => updateExam('start_time', v)} required />
              <Field label="End Time *" type="datetime-local" value={examData.end_time} onChange={v => updateExam('end_time', v)} required />
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">Description</label>
              <textarea
                value={examData.description}
                onChange={e => updateExam('description', e.target.value)}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                rows={3}
                placeholder="Optional exam description or instructions..."
              />
            </div>

            {/* Toggles */}
            <div className="grid grid-cols-3 gap-4">
              {[
                { field: 'shuffle_questions', label: 'Shuffle Questions' },
                { field: 'shuffle_options', label: 'Shuffle Options' },
                { field: 'proctoring_enabled', label: 'AI Proctoring' },
              ].map(toggle => (
                <label key={toggle.field} className="flex items-center gap-2 cursor-pointer">
                  <input
                    type="checkbox"
                    checked={examData[toggle.field]}
                    onChange={e => updateExam(toggle.field, e.target.checked)}
                    className="w-4 h-4 accent-blue-600"
                  />
                  <span className="text-sm text-gray-700">{toggle.label}</span>
                </label>
              ))}
            </div>

            <button
              type="submit"
              disabled={saving}
              className="w-full bg-blue-600 hover:bg-blue-700 disabled:bg-blue-400 text-white font-semibold py-3 rounded-xl transition"
            >
              {saving ? 'Creating...' : 'Create Exam & Continue →'}
            </button>
          </div>
        </form>
      )}

      {/* Step 2: Questions */}
      {step === 2 && (
        <div className="max-w-3xl">
          <div className="flex justify-between items-center mb-4">
            <h2 className="font-bold text-gray-800">{questions.length} Question{questions.length !== 1 ? 's' : ''}</h2>
            <button onClick={addQuestion} className="bg-blue-50 text-blue-700 hover:bg-blue-100 px-4 py-2 rounded-lg text-sm font-medium transition">
              + Add Question
            </button>
          </div>

          <div className="space-y-4">
            {questions.map((q, idx) => (
              <div key={idx} className="bg-white rounded-xl shadow-sm p-5">
                <div className="flex justify-between items-center mb-4">
                  <span className="font-semibold text-gray-700">Question {idx + 1}</span>
                  {questions.length > 1 && (
                    <button onClick={() => removeQuestion(idx)} className="text-red-500 hover:text-red-700 text-sm">Remove</button>
                  )}
                </div>

                <div className="space-y-3">
                  <div>
                    <label className="text-xs font-medium text-gray-600 mb-1 block">Question *</label>
                    <textarea
                      value={q.question_text}
                      onChange={e => updateQuestion(idx, 'question_text', e.target.value)}
                      className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                      rows={2}
                      placeholder="Enter question..."
                    />
                  </div>

                  <div className="grid grid-cols-2 gap-3">
                    {['A', 'B', 'C', 'D'].map(opt => (
                      <div key={opt}>
                        <label className="text-xs font-medium text-gray-600 mb-1 flex items-center gap-1">
                          <input
                            type="radio"
                            name={`correct_${idx}`}
                            value={opt}
                            checked={q.correct_option === opt}
                            onChange={() => updateQuestion(idx, 'correct_option', opt)}
                            className="accent-green-600"
                          />
                          Option {opt} {q.correct_option === opt && <span className="text-green-600 text-xs">(Correct)</span>}
                        </label>
                        <input
                          value={q[`option_${opt.toLowerCase()}`]}
                          onChange={e => updateQuestion(idx, `option_${opt.toLowerCase()}`, e.target.value)}
                          className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                          placeholder={`Option ${opt}...`}
                        />
                      </div>
                    ))}
                  </div>

                  <div className="flex gap-3">
                    <div className="flex-1">
                      <label className="text-xs font-medium text-gray-600 mb-1 block">Marks</label>
                      <input type="number" value={q.marks} onChange={e => updateQuestion(idx, 'marks', parseInt(e.target.value))}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-blue-500 outline-none" min={1} />
                    </div>
                    <div className="flex-1">
                      <label className="text-xs font-medium text-gray-600 mb-1 block">Difficulty</label>
                      <select value={q.difficulty} onChange={e => updateQuestion(idx, 'difficulty', e.target.value)}
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-blue-500 outline-none">
                        <option value="easy">Easy</option>
                        <option value="medium">Medium</option>
                        <option value="hard">Hard</option>
                      </select>
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>

          <div className="mt-6 flex gap-3">
            <button onClick={addQuestion} className="flex-1 border-2 border-dashed border-blue-300 text-blue-600 py-3 rounded-xl hover:bg-blue-50 transition font-medium">
              + Add Another Question
            </button>
            <button
              onClick={handleSaveQuestions}
              disabled={saving}
              className="flex-1 bg-green-600 hover:bg-green-700 disabled:bg-green-400 text-white font-semibold py-3 rounded-xl transition"
            >
              {saving ? 'Saving...' : `Save ${questions.length} Questions ✓`}
            </button>
          </div>
        </div>
      )}
    </Layout>
  );
}

function Field({ label, value, onChange, type = 'text', placeholder, required }) {
  return (
    <div>
      <label className="block text-sm font-medium text-gray-700 mb-1">{label}</label>
      <input
        type={type}
        value={value}
        onChange={e => onChange(e.target.value)}
        placeholder={placeholder}
        required={required}
        className="w-full px-3 py-2 border border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-blue-500 outline-none"
      />
    </div>
  );
}
